function classLevelName(name){
  if(!name) return null;
  const n=String(name).replace(/\s/g,"");
  if(/オープン|ＯＰ|\(L\)|（Ｌ）|リステッド/.test(n)) return 7;
  if(/3勝|３勝|1600万/.test(n)) return 6;
  if(/2勝|２勝|1000万/.test(n)) return 5;
  if(/1勝|１勝|500万/.test(n)) return 4;
  if(/未勝利/.test(n)) return 3;
  if(/新馬/.test(n)) return 3;
  if(/A1|A2|Ａ1|Ａ2|A級/.test(n)) return 6;
  if(/B1|B2|B3|Ｂ1|B級/.test(n)) return 5;
  if(/C1|C2|C3|Ｃ1|C級/.test(n)) return 4;
  if(/認|2歳|3歳|２歳|３歳/.test(n)) return 3;
  if(/賞|特別|記念|杯|盃|ステークス|カップ|オープン/.test(n)) return 6; // 重賞・特別（グレード不明）
  return null;
}

function classLevelFromBlock(data02html, name){
  const g=(data02html||"").match(/Icon_GradeType(\d)/);
  if(g){ const v=+g[1]; if(v===1)return 10; if(v===2)return 9; if(v===3)return 8; }
  if(/Jpn\s*Ⅰ|JpnⅠ|Jpn1/.test(data02html||"")) return 10;
  if(/Jpn\s*Ⅱ|JpnⅡ|Jpn2/.test(data02html||"")) return 9;
  if(/Jpn\s*Ⅲ|JpnⅢ|Jpn3/.test(data02html||"")) return 8;
  return classLevelName(name);
}

function parsePastRace(cellHtml){
  const get=(cls)=>{ const m=cellHtml.match(new RegExp('class="'+cls+'"[^>]*>([\\s\\S]*?)</div>')); return m?m[1].replace(/<[^>]+>/g," ").replace(/&nbsp;/g," ").replace(/\s+/g," ").trim():""; };
  const rid=(cellHtml.match(/\/race\/(\d{12})/)||[])[1]||null;
  const d01=get("Data01");    // タグ除去後 "2026.05.20 門別 11" など（日付・場・着順）
  // 着順の取得。netkeiba は着順1〜3着を色分けするため、class="Num" 以外の要素で
  // 出すことがある（class="Num" だけを見ると1〜3着が丸ごと消える＝報告のあった不具合）。
  // そこで「Numクラス」に依存せず、タグ除去済み Data01 の末尾トークンから着順を取る。
  //   例 "2026.05.20 門別 3" → 3着 /  "2026.01.19 名古屋 1" → 1着
  // 取消・除外・中止は数字にならないので null。数字が無ければ Num系クラスからも試す（保険）。
  let rank=null;
  const parts=d01.split(/\s+/).filter(Boolean);
  const lastTok=parts.length?parts[parts.length-1]:"";
  if(/^\d{1,2}$/.test(lastTok)){
    rank=+lastTok;                 // Data01末尾が着順（"… 門別 3"）
  } else {
    // Data01末尾が数字でない（着順が別要素/別セルにある構造）→ セル全体から着順要素を探す。
    // class名に依存しないよう、Data01直後〜Data02手前の最初の 1〜2桁数字spanを着順とみなす。
    const seg = cellHtml.match(/class="Data01"[\s\S]*?(?=class="Data0[2-9]"|$)/);
    const rm = (seg?seg[0]:cellHtml).match(/>\s*(\d{1,2})\s*<\/(?:span|div)>/);
    if(rm) rank=+rm[1];
    else { const nm=cellHtml.match(/class="[^"]*\bNum\b[^"]*"[^>]*>\s*(\d{1,2})\s*</); if(nm) rank=+nm[1]; }
  }
  const d05=get("Data05");                                   // "ダ2400 2:36.0 良"
  const d03=get("Data03");                                   // "12頭 10番 6人 騎手 56.0"
  const d06=get("Data06");                                   // "6-6-7-8 (38.7) 484(-16)"
  const surf=(d05.match(/(芝|ダ)/)||[])[1]||null;
  const dist=+((d05.match(/[芝ダ](\d{3,4})/)||[])[1]||0)||null;
  // 馬場状態。地方(nar)は「稍」「不」の1文字略記で出ることがあるため、2文字表記も1文字も拾う。
  //   良 / 稍(重) / 重 / 不(良)  → 正規化して 良・稍重・重・不良 に統一。
  //   ※順序に注意: 「稍重」「不良」を先に試し、無ければ1文字略記を拾う。
  let going=null;
  const gm=(d05||"").match(/稍重|不良|良|稍|不|重/);
  if(gm){ const g=gm[0]; going = g==="稍"?"稍重" : g==="不"?"不良" : g; }
  const fieldN=+((d03.match(/(\d{1,2})頭/)||[])[1]||0)||null;
  const pop=+((d03.match(/(\d{1,2})人/)||[])[1]||0)||null;
  // 騎手: Data03 = "頭数 馬番 人気 騎手名 斤量"。人気と斤量の間が騎手
  let jockey=null;
  const jm=d03.match(/\d{1,2}人\s*([^\d\s][^\d]*?)\s*\d{2}\.\d/);
  if(jm) jockey=jm[1].trim().replace(/\s+/g,"");
  const passing=(d06.match(/([\d]+(?:-[\d]+){1,3})/)||[])[1]||null;   // 通過順
  const last3f=+((d06.match(/\((\d{2}\.\d)\)/)||[])[1]||0)||null;
  // 馬体重(増減): "480(+4)" "456(-2)" "470(0)"
  const wm=d06.match(/(\d{3})\(\s*([+-]?\d+)\s*\)/);
  const weight = wm? +wm[1] : null;
  const wdiff = wm? +wm[2] : null;
  // 走破タイム "2:36.0" → 秒
  const tm=d05.match(/(\d+):(\d{2}(?:\.\d)?)/);
  const time = tm? (+tm[1]*60 + parseFloat(tm[2])) : null;
  const turn=rid?turnOfRid(rid):null;
  // レース日付（Data01先頭 "2026.04.12"）→ YYYYMMDD
  let rdate=null;
  const dm=d01.match(/(\d{4})\.(\d{1,2})\.(\d{1,2})/);
  if(dm) rdate = dm[1]+String(dm[2]).padStart(2,"0")+String(dm[3]).padStart(2,"0");
  // 脚質: 通過順の最初のコーナー位置/頭数で判定
  let style=null;
  if(passing&&fieldN){ const first=+passing.split("-")[0]; const r=first/fieldN;
    style = r<=0.20?"逃":(r<=0.45?"先":(r<=0.75?"差":"追")); }
  const d02=(cellHtml.match(/class="Data02"[^>]*>([\s\S]*?)<\/div>/)||[])[1]||"";
  const d02name=(d02.match(/>\s*([^<>\n]+?)\s*</)||d02.match(/([^<>\n]+)/)||[])[1]||"";
  const clv=classLevelFromBlock(d02, d02name);
  return {rid, rank, surf, dist, going, time, fieldN, pop, passing, last3f, turn, style, jockey, weight, wdiff, jump:/障/.test(d05||""), clv, rdate,
          track: rid?trackNameOfRid(rid):null};
}

function parseShutuba(html){
  const entries={}; const order=[]; const scratched=[];
  /* ★2026-07-26追加: ばんえい(帯広=65)判定★
     斤量の表記が平地と全く違う（平地48-63kg台 vs ばんえい400-700kg台）ため、
     斤量パースを場によって分ける。html中のrace_id(4桁年+場2桁+…)から判定する。 */
  const isBaneiPage = /race_id=(\d{4}65\d{6})|myhorse_(\d{4}65\d{6})/.test(html);
  // 馬柱は各馬が大きな行。/horse/ を含む tr を1頭として扱う
  let rows=html.match(/<tr[^>]*class="[^"]*HorseList[^"]*"[\s\S]*?<\/tr>/g);
  if(!rows||!rows.length){ rows=(html.match(/<tr[\s\S]*?<\/tr>/g)||[]).filter(t=>/\/horse\/[A-Za-z]?\d+/.test(t)); }
  rows.forEach(r=>{
    // 馬柱: 枠=<td class="WakuN">N</td>, 馬番=<td class="Waku">M</td>（数字サフィックス無し）
    const w=r.match(/class="Waku(\d)"/);
    let u=r.match(/class="Waku"[^>]*>\s*(\d{1,2})\s*</);   // 馬番（馬柱の正式位置）
    if(!u) u=r.match(/class="[^"]*Umaban[^"]*"[^>]*>\s*(\d{1,2})/) || r.match(/<td[^>]*class="[^"]*Txt_C[^"]*"[^>]*>\s*(\d{1,2})\s*</);
    // 馬名は Horse_Info セル内の馬名リンク（Horse02）から取る。近走の相手馬リンクを拾わないよう限定
    const info=r.match(/class="Horse_Info"[\s\S]*?(?=<td|<\/tr>)/);
    let n=null;
    if(info){ n=info[0].match(/\/horse\/([A-Za-z]?\d+)\/?"[^>]*>\s*(?:<[^>]+>\s*)*([^<]{1,30}?)\s*</); }
    if(!n) n=r.match(/\/horse\/([A-Za-z]?\d+)[^"]*"[^>]*title="([^"]{1,30})"/); // titleフォールバック
    if(!n) n=r.match(/\/horse\/([A-Za-z]?\d+)[^"]*"[^>]*>\s*([^<]{1,30}?)\s*</);
    if(!u||!n) return;
    const num=String(parseInt(u[1],10)), name=n[2].trim(), hid=n[1];
    // 出走取消・競走除外: entriesに入れず scratched へ退避（採点・印・買い目から完全除外）。過去走セルは判定前に除去
    const _rCur=r.replace(/<td[^>]*class="[^"]*\bPast\b[^"]*"[\s\S]*?<\/td>/g,"");
    if(/class="[^"]*Cancel[^"]*"/.test(_rCur) || /取消|除外/.test(_rCur.replace(/<[^>]+>/g," "))){ scratched.push({num, name, waku:(w?+w[1]:null)}); return; }
    if(entries[num]) return;
    let jockey="", jockeyId=null;
    const jm=r.match(/\/jockey\/(?:result\/recent\/)?([A-Za-z0-9]{4,7})\/?[^"]*"[^>]*>\s*([^<]{1,16}?)\s*</);
    if(jm){ jockeyId=jm[1]; jockey=jm[2].trim(); }
    // 斤量
    /* ★2026-07-26追加: ばんえいの斤量は400-700kg台（そりを曳く負担重量）で平地の
       48-63kg台と全く違う。従来の正規表現は行全体から48-63の2桁.1桁数値を拾うため、
       過去走のタイム表記("1:53.5"の"53.5")を誤って斤量として拾っていた
       （ばんえいの走破タイムは200mで50-90秒台のことが多く、48-63と衝突しやすい）。
       ばんえいはJockeyセル内の素の<span>NNN.N</span>（コメントアウトされた騎手
       リンクの外）から正しく取る。 */
    let kinryo=null;
    if(isBaneiPage){
      const jCell=r.match(/class="Jockey"[\s\S]*?<\/td>/);
      if(jCell){
        const jc=jCell[0].replace(/<!--[\s\S]*?-->/g,"");
        const kinM=jc.match(/<span>\s*(\d{2,3}\.\d)\s*<\/span>/);
        if(kinM) kinryo=+kinM[1];
      }
    } else {
      const kin=r.match(/\b(\d{2}\.\d)\b/g);
      if(kin){ for(const k of kin){ const v=+k; if(v>=48&&v<=63){ kinryo=v; break; } } }
    }
    // 今走の馬体重(増減): class="Weight" セル内 "482(-4)"（当日発表後のみ。未発表は空）
    let weight=null, wdiff=null;
    // 所属アイコン: Icon_kakuChi=カク地(地方所属馬が交流競走に出走)。
    //   ※地方主催レースでは地元所属馬にアイコンが付かないため、「アイコン無し=JRA」とは
    //     断定できない。交流戦の判定にはレース名を使う（betPlan/raceFocus参照）。
    //     ここでは参考情報として、カク地マークの有無だけ記録する。
    let belong=null;
    if(/Icon_MaruChi/.test(r)) belong="地";          // JRA: 地方所属馬(マル地)
    else if(/Icon_MaruGai/.test(r)) belong="外";     // JRA: 外国馬(マル外)
    else if(/Icon_kaku[A-Za-z]*Gai/.test(r)) belong="外";  // カク外
    else if(/Icon_HorseMark\s+Icon_kaku[A-Za-z]*Chi/.test(r)) belong="カク地";
    const wcell=r.match(/class="Weight"[^>]*>([\s\S]*?)<\/td>/);
    if(wcell){ const wt=wcell[1].replace(/<[^>]+>/g," ").replace(/&nbsp;/g," ");
      const wm=wt.match(/(\d{3})\s*\(\s*([+-]?\d+)\s*\)/);
      if(wm){ weight=+wm[1]; wdiff=+wm[2]; }
      else { const wo=wt.match(/\b(\d{3})\b/); if(wo) weight=+wo[1]; }  // 増減無し(新馬等)
    }
    // 近走（Past セル）を最大5走パース。
    // netkeiba は着順1〜3着の走に class="Past Ranking_1/2/3"（色分け）を付ける。
    // 旧 /class="Past"[\s\S]*?<\/td>/ は class="Past" 完全一致前提のため、この複合クラスの
    // セルを正しく1セルとして拾えず、好走した近走(1〜3着)が丸ごと欠落していた
    // （＝報告のあった「3着だけ入ってない」の真因）。td単位で Past を含むセルを取る。
    const pastCells=r.match(/<td[^>]*class="[^"]*\bPast\b[^"]*"[\s\S]*?<\/td>/g)||[];
    const past=pastCells.map(parsePastRace)
      .filter(p=> p.rid || p.rank!=null || p.rdate || p.dist )   // 空(休養)セルを除外
      .slice(0,5);                                               // 有効走の中から最大5走
    // 血統・厩舎: Horse_Info セル内 Horse01=父, (母父), 所属・調教師
    let sire=null, damsire=null, trainer=null;
    // 調教師ID（/trainer/ID または /trainer/result/recent/ID）
    let trainerId=null;
    const trm=r.match(/\/trainer\/(?:result\/recent\/)?([0-9a-z]{4,7})\/?"/);
    if(trm && trm[1]!=="result") trainerId=trm[1];
    if(info){
      const txt=info[0].replace(/<[^>]+>/g,"\n").replace(/&nbsp;/g," ");
      const lines=txt.split("\n").map(s=>s.trim()).filter(s=>s);
      const idxName=lines.findIndex(s=>s===n[2]);
      for(let i=0;i<lines.length;i++){
        const ln=lines[i];
        if(ln===n[2]) continue;
        const ds=ln.match(/^\(([^)]{2,20})\)$/); if(ds&&!damsire){ damsire=ds[1]; continue; }
        if(/美浦|栗東|地方|・/.test(ln) && /[・]/.test(ln) && !trainer){ trainer=ln.replace(/\s+/g,""); continue; }
        if(!sire && /^[ァ-ヶA-Za-z][ァ-ヶーA-Za-z' .]{1,22}$/.test(ln) && (idxName<0||i<idxName)) sire=ln;
      }
    }
    // ブリンカー: 馬名直後の <span class="Mark">B</span>（Horse_Info内に限定。Rank_B等の誤検出を避ける）
    let blinker=false;
    if(info){ blinker=/<span class="Mark">\s*B\s*<\/span>/.test(info[0]); }
    if(!blinker){ // フォールバック: この馬のhorseリンク直後のMark
      const re2=new RegExp('/horse/'+hid+'[^"]*"[^>]*>\\s*'+name.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\s*</a>\\s*<span class="Mark">\\s*B');
      blinker=re2.test(r);
    }
    // 性齢: 牡4 / 牝3 / セ7
    let sexAge=null;
    const barei=r.match(/class="Barei[^"]*"[^>]*>\s*([牡牝セせん騸]+)\s?(\d{1,2})/);
    if(barei) sexAge=barei[1].replace("せん","セ").replace("騸","セ")+barei[2];
    else { const sa=r.match(/([牡牝セせん騸]+)\s?(\d{1,2})/); if(sa) sexAge=sa[1].replace("せん","セ").replace("騸","セ")+sa[2]; }
    // 性別記号だけ（牡/牝/セ）
    let sex=null; if(sexAge){ const sm=sexAge.match(/^[牡牝セ]/); if(sm) sex=sm[0]; }
    entries[num]={num, name, waku:w?+w[1]:null, jockey, jockeyId, kinryo, hid, past, sire, damsire, trainer, trainerId, blinker, weight, wdiff, sexAge, sex, belong};
    order.push(num);
  });
  // コース条件
  const cond={going:null, weather:null, surface:null, dist:null, raceName:null};
  const d01=html.match(/RaceData01[\s\S]{0,400}/);
  if(d01){ const txt=d01[0].replace(/<[^>]+>/g," ").replace(/\s+/g," ");
    const g=txt.match(/馬場[:：]?\s*(良|稍重|重|不良)/); if(g) cond.going=g[1];
    const we=txt.match(/天候[:：]?\s*(晴|曇|雨|小雨|雪|小雪)/); if(we) cond.weather=we[1];
    const c=txt.match(/(芝|ダ|ダート)\s*(\d{3,4})m/); if(c){ cond.surface=c[1]==="芝"?"芝":"ダ"; cond.dist=+c[2]; } }
  const rn=html.match(/RaceName"?[^>]*>\s*([^<\n]{1,40}?)\s*</); if(rn) cond.raceName=rn[1].trim();
  // 今走の回り（race_idから）
  cond.turn = state.raceId? turnOfRid(state.raceId) : null;
  return {entries, order, cond};
}

