let LIVE_BIAS={};

function scoreBreakdown(num, ctx){
  const entries = ctx? ctx.entries : state.entries;
  const e=(entries&&entries[num])||{};
  const past=e.past||[];
  const rid = ctx? ctx.raceId : state.raceId;
  const race = ctx? ctx.race : state.race;
  const curSurf = race&&race.surface;
  const b={ jockey:0, sire:0, trainer:0, drop:0, rest:0, course:0 };
  if(rid && rid.slice(4,6)==="65") return b;   // ばんえいは別系統なので内訳対象外
  // 騎手
  if(e.jockeyId && JOCKEY_STATS[e.jockeyId]){
    const jst=JOCKEY_STATS[e.jockeyId];
    if(jst[1]>=30) b.jockey=+Math.max(0, Math.min(6, (jst[0]-15)*0.25)).toFixed(2);
  }
  // 血統
  if(e.sire && SIRE_STATS[e.sire] && curSurf){
    const ss=SIRE_STATS[e.sire];
    if(ss[0]+ss[2]>=30){
      const isTurf=(curSurf==="芝"); const runs=isTurf?ss[0]:ss[2], wins=isTurf?ss[1]:ss[3];
      let v=0;
      if(runs>=15) v+=Math.max(0, Math.min(3, (wins/runs*100-6)*0.5));
      if(ss[4]!=null && ss[4]>=1.5) v+=Math.min(2, (ss[4]-1.5)*2);
      b.sire=+v.toFixed(2);
    }
  }
  // 調教師
  if(e.trainerId && TRAINER_STATS[e.trainerId]){
    const ts=TRAINER_STATS[e.trainerId];
    if(ts[1]>=30) b.trainer=+Math.max(0, Math.min(3, (ts[0]-18)*0.18)).toFixed(2);
  }
  // 降級ボーナス
  const curClv = classLevelName(race&&race.name) || (ctx&&ctx.curClv) || null;
  if(curClv && past.length){
    let dropBonus=0;
    past.forEach((p,idx)=>{
      if(!p.clv || !p.rank || !p.fieldN) return;
      if(p.clv <= curClv) return;
      const up = Math.min(3, p.clv - curClv);
      const topHalf = p.rank <= Math.ceil(p.fieldN/2);
      const goodRun = p.rank <= Math.max(3, Math.ceil(p.fieldN*0.3));
      const recency = idx===0?1.0 : idx===1?0.7 : 0.5;
      if(goodRun) dropBonus += up*1.4*recency; else if(topHalf) dropBonus += up*0.6*recency;
    });
    b.drop=+Math.min(4, dropBonus).toFixed(2);
  }
  // 休養明け減点
  if(past.length && past[0].rdate && ctx && ctx.raceDate){
    const days = dateDiffDays(past[0].rdate, ctx.raceDate);
    if(days!=null && days>0){
      if(days>=70 && days<120) b.rest=-1.5;
      else if(days>=120 && days<180) b.rest=-3;
      else if(days>=180 && days<300) b.rest=-5;
      else if(days>=300) b.rest=-4;
      else if(days<=5) b.rest=-1;
    }
  }
  // コース有利度
  if(rid){
    const tc=rid.slice(4,6); const fieldN=entries?Object.keys(entries).length:0; const myNum=+num;
    let fb=0, fn=0;
    past.forEach((p,idx)=>{ if(p.style){ fn++; if(p.style==="逃"||p.style==="先") fb+=(idx===0?1:0.7); } });
    const isFront = fn>0 && (fb/fn)>=0.45;
    let bias=COURSE_BIAS[tc];
    if(!bias){ const jb=COURSE_BIAS_JRA[tc]; if(jb) bias = /ダ/.test((ctx&&ctx.race&&ctx.race.surface)||"") ? jb.dirt : jb.turf; }
    const _lb=LIVE_BIAS[tc]; if(_lb && _lb.n>=3){ bias={inner:((bias&&bias.inner)||0)+_lb.inner, front:((bias&&bias.front)||0)+_lb.front}; }
    if(bias && fieldN>0){
      let v=0;
      if(bias.inner){ const ip=1-(myNum-1)/Math.max(1,fieldN-1); v+=ip*bias.inner; }
      if(bias.front && isFront) v+=bias.front;
      b.course=+v.toFixed(2);
    }
  }
  return b;
}

