function speedIndex(e){
  const ps=(e&&e.past)||[]; const figs=[];
  for(let i=0;i<ps.length && i<5;i++){ const p=ps[i];
    if(!p||!p.time||!p.surf||!p.dist||!p.rid) continue;
    const b=BASE_TIME[p.rid.slice(4,6)+p.surf+p.dist]; if(!b) continue;
    let t=p.time;
    if(p.going && p.going!=="良"){ const off=GOING_OFF[p.surf+"|"+p.going]; if(off==null) continue; t-=off; }
    figs.push({fig:(b-t)/0.15, w:(i===0?1:i===1?0.85:0.6)});
  }
  if(!figs.length) return null;
  const best=Math.max(...figs.map(f=>f.fig));
  let wa=0,ws=0; figs.forEach(f=>{wa+=f.fig*f.w;ws+=f.w;});
  const si = 0.6*best + 0.4*(wa/ws);
  // 短距離(特に地方1000m)では時計差が指数に増幅され外れ値化するため、±15でクリップ。
  // 分布の99%は±15内に収まる（門別9,677頭で確認）。順位情報は保ちつつ外れ値の悪影響を抑える。
  return Math.max(-15, Math.min(15, si));
}

